import json
import sys
from pathlib import Path

from src.greeting import greeting


def main() -> None:
    audience = json.loads(Path("config/app.json").read_text())["audience"]
    if "--json" in sys.argv[1:]:
        print(json.dumps({"message": greeting(audience)}))
    else:
        print(greeting(audience))


if __name__ == "__main__":
    main()
